-- then hand-edited: the helper function below must exist before the
-- generated column that uses it.
--
-- array_to_string() is STABLE (it calls element output functions), which a
-- generated column cannot use. For text[] it is deterministic, so this thin
-- wrapper is declared IMMUTABLE.
CREATE OR REPLACE FUNCTION "attestly"."immutable_join"(text[])
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
RETURNS NULL ON NULL INPUT
AS $$ SELECT pg_catalog.array_to_string($1, ' ') $$;
