-- Full-text vector: heading trail weighted A, body weighted B.
ALTER TABLE "attestly"."chunks" ADD COLUMN "tsv" "tsvector" GENERATED ALWAYS AS (setweight(to_tsvector('english'::regconfig, coalesce(attestly.immutable_join(heading_path), '')), 'A') || setweight(to_tsvector('english'::regconfig, coalesce("text", '')), 'B')) STORED;--> statement-breakpoint
